{"command":"python3 -c "
import csv

# Verify RFC 4180 compliance
with open('outputs/t02_eurostat_raw.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    rows = list(reader)

    print(f'Header: {header}')
    print(f'Expected fields: {len(header)}')

    errors = []
    for i, row in enumerate(rows):
        if len(row) != len(header):
            errors.append(f'Row {i}: {len(row)} fields, expected {len(header)}')

    if errors:
        for e in errors[:10]:
            print(e)
    else:
        print('All rows have correct number of fields (RFC 4180 compliant)')

    # Check for quoted fields
    quoted_count = 0
    for row in rows:
        for field in row:
            if '\"' in field:
                quoted_count += 1
    print(f'Rows with quoted fields: {quoted_count}')
""}

